#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float2 amzp_centerPoint;
uniform float amzp_strength;
uniform float amzp_radius;
uniform float amzp_colorAberration;
uniform float amzp_centerChannel;
uniform float amzp_mode;


        const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);

        float4 getBlurred(float channelStrength) {
          float2 texelSize = 1.0 / getTexSize((screen.zw/1.0));
          float Radius = amzp_radius;
          float T = channelStrength;

          float2 UV = amzScreenNorm();

          float2 CENTER = amzp_centerPoint*float2(-1,-1);

          float2 diff1 = amzLayerCenter()-CENTER;
          diff1.y = screen.zw.y - diff1.y;
          float2 diff = diff1 /screen.zw;

          UV -= diff;
          float2 convRate = float2(1,1);
          if(screen.zw.y > screen.zw.x)
              convRate.y=(screen.zw.y/screen.zw.x);
          else
              convRate.x=(screen.zw.x/screen.zw.y);
          UV *= convRate;

          float Dist = length(UV);

          float4 color = float4(0.0);

          if ( Dist < Radius )
          {
              float speed = 0.0;
              float localPower = (Radius - Dist) / Radius;
              {
                float A = ( T <= 0.5 ) ? mix( 0.0, 1.0, T/0.5 ) : mix( 1.0, 0.0, (T-0.5)/0.5 );
                float Theta = localPower * localPower * A * 8.0 * 3.14159;
                float l = Dist * Theta;
                speed = abs(l/texelSize.x*10.0);
              }
              float nSamples = float(clamp(speed, 1.01, 2000.01));

              float2 v = UV/nSamples;
              float2 c = float2(0.0);
              float count = 0.0;
              for(float d = max(Radius - abs(amzp_strength)*localPower, Dist); d <= Radius; d += 1.0/nSamples) {
                  float Percent = (Radius - d) / Radius;
                  float2 cc = UV - c;
                  c += v;
                  float A = ( T <= 0.5 ) ? mix( 0.0, 1.0, T/0.5 ) : mix( 1.0, 0.0, (T-0.5)/0.5 );
                  float Theta = Percent * Percent * A * 8.0 * 3.14159;
                  float S = sin( Theta );
                  float C = cos( Theta );
                  float2 res = float2( dot(cc, float2(C, -S)), dot(cc, float2(S, C)) );
                  res /= convRate;
                  res += diff;
                  color += amzTexture(0, res);
                  count += 1.0;
              }
              color /= count;
          }
          else {
              UV /= convRate;
              UV += diff;
              color = amzTexture(0, UV);
          }
          return color;
        }

        void amzRender() {

          float3 offset = float3(0.0);
          if( int(amzp_centerChannel)==0 ) {
              offset = float3(0.0, -1.0, 1.0);
          } else if( int(amzp_centerChannel)==1 ) {
              offset = float3(-1.0, 0.0, 1.0);
          } else {
              offset = float3(-1.0, 1.0, 0.0);
          }
          offset *= amzp_colorAberration;
          float4 redBlurred = getBlurred((1.0+offset.r)*amzp_strength);
          float4 greenBlurred = getBlurred((1.0+offset.g)*amzp_strength);
          float4 blueBlurred = getBlurred((1.0+offset.b)*amzp_strength);
          float4 outColor = float4(redBlurred.r,
                              greenBlurred.g,
                              blueBlurred.b,
                              (redBlurred.a+greenBlurred.a+blueBlurred.a)/3.0);
          float4 colorMid, colorLow, colorHigh;
          if( int(amzp_centerChannel)==0 ) {
              colorMid = redBlurred;
              colorLow = greenBlurred;
              colorHigh = blueBlurred;
          } else if( int(amzp_centerChannel)==1 ) {
              colorMid = greenBlurred;
              colorLow = redBlurred;
              colorHigh = blueBlurred;
          } else {
              colorMid = blueBlurred;
              colorLow = redBlurred;
              colorHigh = greenBlurred;
              offset = float3(-1.0, 1.0, 0.0);
          }
          if( int(amzp_mode)==0 ) {
              amzOutput = outColor * colorMid.a;
          } else if( int(amzp_mode)==1 ) {
              float4 r = float4(outColor.r, 0.0, 0.0, outColor.r);
              float4 g = float4(0.0, outColor.g, 0.0, outColor.g);
              float4 b = float4(0.0, 0.0, outColor.b, outColor.b);
              float4 m = (r + g + b) / 3.;
              float4 c = float4(0.0,0.0,0.0,0.0);
              float4 l = float4(dot(luminanceWeighting * colorMid.rgb, float3(1.0)));
              c = m + (c*(1.0-m.a));
              c = l + (c*(1.0-l.a));
              amzOutput = c;
          } else if( int(amzp_mode)==2 ) {
              amzOutput = float4(outColor.rgb,colorMid.a);
          } else {
              amzOutput = outColor*((colorLow.a + colorMid.a + colorHigh.a)/3.);
          }
        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

